import{_ as i,c as r,o,ah as l}from"./chunks/framework.Ch_PcVtW.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART3/9/0_context_summary.md","filePath":"scripts/output/PART3/9/0_context_summary.md"}'),e={name:"scripts/output/PART3/9/0_context_summary.md"};function s(n,t,a,S,_,g){return o(),r("div",null,[...t[0]||(t[0]=[l('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本文围绕五位BMSG个人艺人SKY-HI、Novel Core、Aile The Shota、edhiii boi与REIKO组成的音乐crew“BMSG POSSE”展开。SKY-HI说明，POSSE并非传统团体，而是建立在五位艺人各自人格与创作方向已经成熟基础上的“共同游乐场”。文章重点讨论edhiii boi与REIKO个人艺人成长及出道时机、POSSE成立的管理与创作意图，以及通过无压力、无功利的音乐游戏激发创造力。与此同时，POSSE也被寄予连接个人活动、拓展亚洲市场、与海外crew合作的期待。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>人物与团体名称</strong>：SKY-HI、Novel Core、Aile The Shota、edhiii boi、REIKO、BMSG POSSE、BE:FIRST、MAZZEL须统一拼写。</li><li><strong>crew与group的区别</strong>：POSSE明确是“crew（音乐圈层／创作团队）”，不能简单译为“组合”或“团体”。</li><li><strong>“个人格”</strong>：指艺人作为独立创作者形成的艺术人格与表达主体，不宜译成普通性格。</li><li><strong>“グループ人格”</strong>：与个人艺术人格相对，强调集体身份和群体意识。</li><li><strong>“フックアップ”</strong>：音乐行业语境中指发掘、支持并推介新人，不宜直译为“钩住”。</li><li><strong>音乐术语</strong>：flow（说唱节奏／唱法）、hook（副歌或记忆点）、HIPHOP、artwork（视觉作品／艺术设计）、feature（合作演出／客串）需保持行业准确性。</li><li><strong>“絵面”</strong>：指五人同框时产生的视觉效果和反差感，可译为“画面感”“同框效果”，不要译成单纯“外貌”。</li><li><strong>“腹をくくる”</strong>：表示下定决心、做好心理准备，不是字面意义上的“收腹”。</li><li><strong>“緩と急”</strong>：指生活与创作中的松弛和紧张、张弛变化，不宜机械译为“慢与快”。</li><li><strong>“大喜利”</strong>：日本即兴接梗、创意回答式的游戏，可根据语境译为“即兴接梗游戏”。</li><li><strong>“実家に帰ってきたよう”</strong>：是比喻性的归属感表达，应保留口语化和心理感受。</li><li><strong>“世の中は正しいことをやっていると正しい方向に進む”</strong>：带有个人信念色彩，不宜过度改写成绝对的成功学判断。</li><li><strong>“5年後、10年後”</strong>：强调文化开拓的长期意义，不能仅按即时成绩理解。</li><li><strong>“3人は飲まない”</strong>：语境略带玩笑，需结合REIKO控酒及五人关系处理，避免造成事实歧义。</li><li><strong>语气层次</strong>：采访主体应兼具管理者的理性、艺术家的热情，以及熟人间的轻松幽默；括号中的“（笑）”不宜全部删去。</li><li><strong>客观旁白</strong>：加粗部分是第三人称编辑叙述，与SKY-HI第一人称回答需明确区分。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li>统一采用“BMSG POSSE（以下简称POSSE）”等译法，并保留艺人原名及主要英文行业术语。</li><li>重点呈现POSSE“不是为了替代个人活动，而是让成熟的个人艺人在集体中自由创作”的核心逻辑。</li><li>保留SKY-HI对edhiii boi长期培养、REIKO自我肯定与亚洲拓展的管理观察，避免译成单纯的宣传文案。</li><li>“玩乐”“游乐场”“孩子在沙坑里玩”等意象是全文核心，应译得自然且具有画面感。</li><li>对“真面目、焦虑、责任、商业考量”与“无邪地玩音乐”之间的张力要准确传达。</li><li>维持第一人称访谈的口语节奏，避免过度书面化；同时保证出版物所需的准确、克制与连贯。</li><li>对ASAP Mob、Odd Future、BROCKHAMPTON、YENTOWN、KANDYTOWN、BAD HOP等crew名称不擅自翻译，可在首次出现时补充“音乐crew”。</li></ul>',6)])])}const h=i(e,[["render",s]]);export{u as __pageData,h as default};
